import {readFileSync,readdirSync} from 'node:fs';
import {database as base,id,scopes} from './learning-dashboard-db.mjs';
import {postgresClient} from './learning-acceptance.mjs';
export {id,scopes};
export const migrationPath='supabase/migrations/'+readdirSync('supabase/migrations').find(n=>n.endsWith('_sprint_16_1b_written_work.sql'));
export const definition={schemaVersion:'extended-text-v1',title:'Synthetic writing task',prompt:'Write a short description using the supplied classroom context.',locale:'en',minWords:80,maxWords:100,wordCountConvention:'unicode-whitespace-v1',baselineRequired:false,assistance:{spellcheck:false,platformHints:false},source:{kind:'synthetic-fixture'},outcomes:['synthetic-description'],criteria:[{key:'task',label:'Task and audience',descriptors:['No evidence','Limited','Mostly meets','Meets']},{key:'organisation',label:'Organisation',descriptors:['No evidence','Limited','Mostly clear','Clear']},{key:'vocabulary',label:'Vocabulary',descriptors:['No evidence','Limited','Mostly suitable','Suitable']},{key:'grammar',label:'Grammar and clarity',descriptors:['No evidence','Limited','Mostly clear','Clear']}]};
export const fixtureSQL=`alter table profiles add column display_name text;update profiles set display_name='Synthetic learner';insert into profiles(id,role,account_status,display_name) values('${id(30)}','content_admin','active','Synthetic reviewer');insert into auth.users(id) values('${id(20)}'),('${id(21)}');insert into auth.sessions(id,user_id) values('${id(420)}','${id(20)}'),('${id(421)}','${id(21)}');`;
export async function seed(db){await db.exec(fixtureSQL);for(let i=0;i<scopes.length;i++){const s=scopes[i];await db.query("insert into written_task_versions(id,task_key,version_no,subject_program_id,curriculum_release_id,unit_id,definition,status,reviewed_by,reviewed_at,review_evidence) values($1,'fixture-task',1,$2,$3,$4,$5,'approved',$6,now(),'{\"fixture\":true,\"qaPassed\":true,\"reviewReference\":\"synthetic\",\"sourceComparisonReference\":\"synthetic\"}')",[id(1000+i),id(s.programme),id(s.release),id(s.unit),JSON.stringify(definition),id(30)]);}}
export async function database(options={}){const db=await base({...options,...(process.env.PHASE3_POSTGRES_17_CI==='1'?{client:await postgresClient()}:{} )});try{await db.exec(readFileSync(migrationPath,'utf8'));await seed(db);return db;}catch(e){await db.close();throw e;}}
export function context(index=0,teacher=false){const s=scopes[index];return{curriculumReleaseId:id(s.release),unitId:id(s.unit),...(teacher?{assignmentId:id(index===2?352:351)}:{enrollmentId:id(s.enrollment)})};}
export async function call(db,action,payload={},options={}){const teacher=['queue','inspect','review'].includes(action);return(await db.query('select service_written_work($1,$2,$3,$4,$5) result',[options.actor??id(teacher?20:10),options.auth??id(teacher?420:401),action,JSON.stringify(options.context??context(options.index??0,teacher)),JSON.stringify(payload)])).rows[0].result;}
